/**Function********************************************************************

  Synopsis    [Returns the next prime &gt;= p.]

  Description []

  SideEffects [None]

******************************************************************************/
unsigned int
Cudd_Prime(
  unsigned int  p)
{
    var i, pn int32;

    p--;
    for {
        p++;
        if p&1 {
            pn = 1;
            i = 3;
            for uint32( (i * i)) <= p {
                if p % i == 0 {
                    pn = 0;
                    break;
                }
                i += 2;
            }
        } else {
            pn = 0;
        }

if !(!(pn != 0)) { break }
} 
    return(p);

} /* end of Cudd_Prime */


